# -------------- References ---------------
class Ref:
    def __init__(self,full,target):
        self.full=full; self.target=target; self.type='other'; self.name=full
        if full=='HEAD':
            self.type='head'; self.name='HEAD'
        elif full.startswith('refs/heads/'):
            self.type='branch'; self.name=full[len('refs/heads/'):]
        elif full.startswith('refs/tags/'):
            self.type='tag'; self.name=full[len('refs/tags/'):]  # may upgrade annotated
        elif full.startswith('refs/remotes/'):
            self.type='remote'; self.name=full[len('refs/remotes/'):]
        elif full=='refs/stash':
            self.type='stash'; self.name='stash'
        elif full.startswith('refs/notes/'):
            self.type='note'; self.name=full[len('refs/'):]  # notes/commits
        elif full.startswith('refs/replace/'):
            self.type='replace'; self.name=full[len('refs/replace/'):]
        elif full.startswith('refs/prefetch/'):
            self.type='prefetch'; self.name=full[len('refs/prefetch/'):]
        else:
            self.name=full[5:] if full.startswith('refs/') else full

def format_ref(ref, opts, repo):
    fmtstr=opts.get('reference-format',"[branch] <tag> {remote}")
    # parse tokens: e.g. "[branch] <tag> hide:remote (head)" etc.
    mapping={}
    for tok in fmtstr.split():
        hidden=False
        if tok.startswith('hide:'):
            mapping[tok[5:]]=None; continue
        # find (type) inside brackets characters: token like [branch] or <tag> or {remote}
        m=re.match(r'^([^\w]*)\(?([a-z-]+)\)?([^\w]*)$',tok) # no
        # simpler: extract word
        wm=re.search(r'([a-z][a-z-]*)',tok)
        if not wm: continue
        typ=wm.group(1)
        # template is tok with typ replaced by %s
        templ=tok.replace(typ,'%s',1)
        mapping[typ]=templ
    typ=ref.type
    # resolve fallbacks
    def get_template(t):
        if t in mapping: return mapping[t]
        if t=='local-tag': return get_template('tag')
        if t=='tracked-remote': return get_template('remote')
        if t=='head': return get_template('branch')
        return get_template('branch')
    # Determine effective type for formatting
    eff=typ
    if typ=='branch' and repo and ref.full==repo.head_ref:
        eff='head'
    if typ=='tag':
        eff='tag' if getattr(ref,'annotated',False) else 'local-tag'
        if 'local-tag' not in mapping and 'tag' in mapping:
            pass
    if typ=='remote' and repo and repo.upstream_ref and ref.full==repo.upstream_ref:
        eff='tracked-remote'
    templ=get_template(eff)
    if templ is None:
        return None
    if templ is None:
        return None
    # if no mapping at all, default branch template
    if '%s' not in templ:
        templ='[%s]'
    return templ % ref.name

class Repo:
    def __init__(self, opts):
        self.opts=opts
        self.git_dir=""; self.is_inside=False; self.cdup=""; self.prefix=""; self.root=""
        self.head_id=""; self.head_ref=""; self.branch=""
        self.refs=[]; self.refs_by_commit={}
        self.is_repo=False; self.fatal=""
        self.upstream_ref=None; self.upstream_name=None
        self._describe_cache={}
    def load(self, allow_fail=False):
        rc,out,err=git_text(["rev-parse","--git-dir","--is-inside-work-tree","--show-cdup","--show-prefix","HEAD","--symbolic-full-name","HEAD"])
        lines=out.splitlines()
        if rc!=0 or not lines:
            self.fatal=err.strip()
            self.is_repo=False
            # config still loaded by caller
            return False
        self.is_repo=True
        if len(lines)>=1: self.git_dir=lines[0]
        if len(lines)>=2: self.is_inside=(lines[1]=='true')
        if len(lines)>=3: self.cdup=lines[2]
        if len(lines)>=4: self.prefix=lines[3]
        # remaining lines: could be HEAD hash, symbolic name, or ambiguous output? git prints hash then ref if present
        rest=lines[4:]
        for l in rest:
            if re.fullmatch(r'[0-9a-f]{40,64}',l): self.head_id=l
            elif l.startswith('refs/'): self.head_ref=l
            elif l=='HEAD': pass
        if self.head_ref.startswith('refs/heads/'):
            self.branch=self.head_ref[len('refs/heads/'):]
        # root
        if self.cdup:
            self.root=os.path.abspath(os.path.join(os.getcwd(),self.cdup))
        else:
            # git_dir may be .git or absolute
            if os.path.basename(self.git_dir)=='.git':
                self.root=os.path.abspath(os.path.dirname(self.git_dir)) if os.path.dirname(self.git_dir) else os.getcwd()
            else:
                self.root=os.getcwd()
        # show-ref (if TIG_LS_REMOTE set, use that shell command)
        self.load_refs()
        # upstream
        rc2,out2,err2=git_text(["rev-parse","--abbrev-ref","@{upstream}"],trace=False)
        if rc2==0 and out2.strip():
            self.upstream_name=out2.strip()
            # find remote ref full
            cand=f"refs/remotes/{self.upstream_name}"
            if any(r.full==cand for r in self.refs):
                self.upstream_ref=cand
        return True
    def load_refs(self):
        self.refs=[]; self.refs_by_commit={}
        env_ls=os.environ.get("TIG_LS_REMOTE")
        refs_data=[]
        if env_ls:
            # run via shell, output format git ls-remote: hash<TAB>ref
            # Trace? Original would trace that command as-is? Skip trace for git wrapper; log raw?
            try:
                p=subprocess.run(env_ls,shell=True,capture_output=True)
                out=p.stdout.decode('utf-8','surrogateescape')
                for line in out.splitlines():
                    if '\t' in line:
                        h,r=line.split('\t',1); refs_data.append((h.strip(),r.strip()))
                    elif ' ' in line:
                        h,r=line.split(None,1); refs_data.append((h.strip(),r.strip()))
            except Exception: pass
        else:
            rc,out,err=git_text(["show-ref","--head","--dereference"])
            for line in out.splitlines():
                parts=line.split()
                if len(parts)>=2:
                    refs_data.append((parts[0],parts[1]))
        # Build annotated detection: refs ending ^{}
        peeled={}
        raw=[]
        for h,r in refs_data:
            if r.endswith('^{}'):
                peeled[r[:-3]]=h
            else:
                raw.append((h,r))
        for h,r in raw:
            if r=='HEAD':
                continue
            ref=Ref(r, peeled.get(r,h))
            ref.annotated = r in peeled
            # If tag ref points to tag object (peeled differs) annotated
            self.refs.append(ref)
            self.refs_by_commit.setdefault(ref.target,[]).append(ref)
        # sort refs_by_commit according to type priority then name
        prio={'head':0,'branch':1,'remote':2,'tracked-remote':2,'tag':3,'local-tag':3,'note':4,'stash':5,'replace':6,'prefetch':7,'other':8}
        def sort_key(ref):
            eff='branch' if (ref.type=='branch' and ref.full==self.head_ref) else ref.type
            # head first
            p=0 if (ref.type=='branch' and ref.full==self.head_ref) else prio.get(ref.type,8)
            return (p, ref.name)
        for k in self.refs_by_commit:
            self.refs_by_commit[k]=sorted(self.refs_by_commit[k],key=sort_key)
    def refs_for(self,commit,opts,include_describe=False,commit_for_describe=None):
        lst=self.refs_by_commit.get(commit,[])
        res=[]
        for r in lst:
            f=format_ref(r,opts,self)
            if f is not None: res.append((f,r))
        return res
    def describe(self,ref="HEAD"):
        if ref in self._describe_cache: return self._describe_cache[ref]
        rc,out,err=git_text(["describe","--tags",ref])
        v=out.strip() if rc==0 else None
        self._describe_cache[ref]=v
        return v

