    elif diff<86400:
        n=diff//3600; unit="hour"; c=f"{n}h"
    elif diff<604800:
        n=diff//86400; unit="day"; c=f"{n}d"
    elif diff<2592000:
        n=diff//604800; unit="week"; c=f"{n}w"
    elif diff<31536000:
