    # lines_data list of dicts mapping col type -> string (preformatted)
    widths={}
    for col in cols:
        if not col.display_bool() and str(col.display()).lower() not in ('auto','default','relative','relative-compact','custom','full','abbreviated','email','email-user','units','short','long'):
            # display False - skip; but some display values are enums when column shown
            # Determine if display is boolean false; enum values mean show
            pass
        w_opt=col.opt('width')
        if w_opt is not None:
            try:
                widths[col.type]=int(str(w_opt).rstrip('%')) if '%' not in str(w_opt) else 0
                if '%' in str(w_opt):
                    widths[col.type]=0
            except: widths[col.type]=0
        else:
            widths[col.type]=0
        if widths[col.type]==0:
            maxw=0
            for d in lines_data:
                v=d.get(col.type,"")
                maxw=max(maxw,str_width(v))
            widths[col.type]=maxw
