        mw=col.opt('maxwidth')
        if mw:
            try:
                if '%' in str(mw):
                    # needs screen width later, cap at load? store? ignore to 100 col
                    limit=int(str(mw).rstrip('%'))
                    widths[col.type]=min(widths[col.type],limit)
                else:
                    widths[col.type]=min(widths[col.type],int(mw))
            except: pass
