def is_column_shown(col):
    d=str(col.display()).lower()
    if d in ('no','false','0','off'): return False
    return True

def format_column_value(col, raw_data):
    # raw_data dict may have precomputed strings
    return raw_data.get(col.type,"")

def render_columns(cols,widths,data, text_col_type=None):
    # returns segments list [(text,color,attrs)] and plain string
    segs=[]; plain_parts=[]
    shown=[c for c in cols if is_column_shown(c)]
    # last expanding column (text/commit-title/file-name if it's last?) will fill rest; we just join with spaces
    for idx,col in enumerate(shown):
        v=data.get(col.type,"")
        color=data.get('_color_'+col.type,'default')
        attrs=data.get('_attrs_'+col.type,0)
        if col.type in ('text','commit-title'):
            # text column: if previous columns exist and line-number shown etc, tig adds vertical separator before text for some views -- handled by caller embedding G_VLINE in v
            segs.append((v,color,attrs)); plain_parts.append(v)
