        if idx!=len(shown)-1:
            segs.append((" ",'default',0)); plain_parts.append(" ")
    plain="".join(plain_parts)
    return segs,plain

# color classification for text lines
def classify_text_line(text,viewname):
    if text.startswith('commit ') and re.match(r'commit [0-9a-f]+',text): return 'commit'
    if text.startswith('Refs:'): return 'pp-refs'
    if text.startswith('Author:'): return 'author-line'
    if text.startswith('AuthorDate:'): return 'date-line'
    if text.startswith('Commit:'): return 'committer-line'
    if text.startswith('CommitDate:'): return 'date-line'
    if text.startswith('Date:'): return 'date-line'
    if text.startswith('Merge:'): return 'pp-merge'
    if text.startswith('diff --'): return 'diff-header'
    if text.startswith('index '): return 'diff-index'
    if text.startswith('@@'): return 'diff-chunk'
    if text.startswith('---') or text.startswith('+++'): return 'diff-header'
    if viewname in ('diff','stage','pager','log'):
        if text.startswith('+') and not text.startswith('+++'): return 'diff-add'
        if text.startswith('-') and not text.startswith('---'): return 'diff-del'
    return 'default'

