            all_data=[self._column_data(vl.data['ref_obj'],vl.data.get('info',{})) for vl in self.lines[1:]]
            self._widths=compute_column_widths(self,cols,all_data)
        data=self._column_data(r,inf)
        shown=[c for c in cols if is_column_shown(c)]
        segs=[]
        for i,col in enumerate(shown):
            v=data.get(col.type,"")
            if col.type=='commit-title':
                segs.append((v,'main-commit',0))
            else:
                w=self._widths.get(col.type,str_width(v))
                segs.append((pad_str(v,w), data.get('_color_'+col.type,'default'),0))
            if i!=len(shown)-1: segs.append((" ",'default',0))
        return segs
    def title(self):
        l=self.current_line()
        if not l: return "[refs] All references"
        if l.data.get('header'):
            return "[refs] All references"
        # reference N of M (excluding header)
        return f"[refs] {l.commit} - reference {self.selected} of {len(self.lines)-1}"
    def current_branch(self):
        l=self.current_line()
        if l and l.data.get('ref_obj'):
            r=l.data['ref_obj']
            if r.type=='branch': return r.name
            if r.type=='remote':
                # branch part after remote/
                return r.name.split('/',1)[1] if '/' in r.name else r.name
