            elif col.type=='author': data['author']=format_author(c.author,col.display())
            elif col.type=='id': data['id']=c.id[:self.app.id_abbrev()]
            elif col.type=='commit-title': data['commit-title']=c.subject
        return data
    def segments(self,line,width):
        # use MainView segments but without graph/refs: Main's segment logic checks opts; stash commit-title default graph no, refs no – our Main segments adds graph if _graph_enabled checks main view, not stash. So custom:
        c=line.data.get('commit_obj')
