        for i,col in enumerate(shown):
            v=data.get(col.type,"")
            if col.type=='commit-title': segs.append((v,'main-commit',0))
            else: segs.append((pad_str(v,self._widths_s.get(col.type,str_width(v))), 'date' if col.type=='date' else 'author' if col.type=='author' else 'default',0))
            if i!=len(shown)-1: segs.append((" ",'default',0))
        return segs
    def title(self):
        l=self.current_line()
        if not l: return "[stash]"
        return f"[stash] stash@{{{self.selected}}} - stash {self.selected+1} of {len(self.lines)}"
    def current_stash(self):
        l=self.current_line(); return l.data.get('stash_name',"") if l else ""
    def current_commit(self):
        # For diff etc, stash commit id is real commit; but %(stash) separate. Title uses stash name.
        return super().current_commit()

