        # git log --encoding=UTF-8 --no-color --pretty=raw --cc --raw <commit> -- .
        # We'll run that (traced) and parse to map path-> last commit (first occurrence in log order)
        path_to_commit={}
        args2=["log","--encoding=UTF-8","--no-color","--pretty=raw","--cc","--raw",commit,"--", path_arg if path_arg else "."]
        rc2,out2,err2=run_git(args2)
        txt2=out2.decode('utf-8','surrogateescape')
        cur=None
        for line in txt2.splitlines():
            if line.startswith('commit '):
                cur={'id':line.split()[1],'author':"",'date':""}
            elif line.startswith('author ') and cur is not None:
                m=re.match(r'author (.*) (\d+ [+-]\d{4})$',line)
                if m: cur['author']=m.group(1); cur['date']=m.group(2)
            elif line.startswith(':') and cur is not None:
                # raw diff: :100644 100644 hash hash M\0? Without -z names on same line after status tab?
                # format: :mode mode hash hash STATUS<TAB>path (and maybe second path)
                if '\t' in line:
                    pth=line.split('\t',1)[1].strip()
                    # remove prefix path?
                    if pth not in path_to_commit:
                        path_to_commit[pth]=cur
        # entries from ls-tree names are full? With -- <path>, git ls-tree shows names relative? For root <.>, names are basenames? observed file.txt etc.
        # Build full file path for entry
        for e in entries:
            full = (self.path+"/"+e['name'].split('/')[-1]) if False else e['name']
            # ls-tree with argument "." returns names as ??? At root, names are filenames. In subdir, ls-tree <commit> -- sub/ returns "sub/inner.txt" full paths? original tree shows only basename in display but file path full.
            # Determine display name = basename
            e['display']=e['name'].rstrip('/').split('/')[-1]
            e['full']=e['name']  # if root, that's file name; if path given, git returns full path
            if self.path and not e['full'].startswith(self.path):
                e['full']=self.path+"/"+e['display']
            # commit info
            info=path_to_commit.get(e['full']) or path_to_commit.get(e['display']) or {}
            e['author']=info.get('author',"")
            e['date']=info.get('date',"")
            e['commit']=info.get('id',"")
        # sort directories first then name
        entries.sort(key=lambda e:(0 if e['type']=='tree' else 1, e['display'].lower()))
        self.entries=entries
        self.lines=[]
        # header line (not selectable?) We'll include as a VLine non-selectable; app selection should skip? Original cursor starts on first entry and header is just display row counted? View offset includes header as row 0 but selection index mapping to lines includes header? Title says file 1 of 3 when selected first entry, selected index 1 if counting header. Our View.selected refers to lines list; we need app to handle non-selectable.
        header_path="/"+(self.path+"/" if self.path else "")
        hv=VLine(f"Directory path {header_path}"); hv.data['kind']='header'; hv.selectable=False; self.lines.append(hv)
        if self.path:
            pv=VLine(".."); pv.data['kind']='parent'; self.lines.append(pv)
            # its rendered columns below special
