        for col in cols:
            if col.type=='mode':
                if e['type']=='tree': data['mode']='drwxr-xr-x'
                else:
                    # parse mode 100644 -> -rw-r--r-- etc, 100755 -> -rwxr-xr-x
                    mode=e['mode']
                    if mode=='100755': data['mode']='-rwxr-xr-x'
                    elif mode=='120000': data['mode']='lrwxrwxrwx'
                    else: data['mode']='-rw-r--r--'
