                        data['file-size']=format_size_units(int(sz))
                    else: data['file-size']=sz
            elif col.type=='date':
                ts,tz=parse_raw_date(e.get('date',"")) if e.get('date') else (0,"+0000")
                data['date']=format_date(ts,tz,col.display(),col.opt('format')) if e.get('date') else ""
            elif col.type=='id': data['id']=e['id'][:self.app.id_abbrev()]
