    def segments(self,line,width):
        if line.data.get('kind')=='header':
            return [(line.text,'header',0)]
        cols=self.app.view_columns('tree')
        if line.data.get('kind')=='parent':
            # "drwxr-xr-x ... .." layout: mode column then blank columns then ..
            # Build using column widths
            if not hasattr(self,'_widths'):
                ad=[self._column_data(e) for e in self.entries]; self._widths=compute_column_widths(self,cols,ad)
            segs=[]; shown=[c for c in cols if is_column_shown(c)]
            for i,col in enumerate(shown):
                if col.type=='mode': segs.append((pad_str('drwxr-xr-x',self._widths.get('mode',10)),'mode',0))
                elif col.type=='file-name': segs.append(("..",'directory',0))
                else:
                    w=self._widths.get(col.type,0); segs.append((" "*w,'default',0))
                if i!=len(shown)-1: segs.append((" ",'default',0))
            return segs
        e=line.data.get('entry')
        if not e: return [(line.text,'default',0)]
        if not hasattr(self,'_widths'):
            ad=[self._column_data(x) for x in self.entries]; self._widths=compute_column_widths(self,cols,ad)
        data=self._column_data(e); shown=[c for c in cols if is_column_shown(c)]; segs=[]
        for i,col in enumerate(shown):
            v=data.get(col.type,"")
            if col.type=='file-name':
                colname='directory' if e['type']=='tree' else 'file'
                segs.append((v,colname,0))
            elif col.type=='file-size':
                w=self._widths.get(col.type,str_width(v)); segs.append((v.rjust(w) if v else " "*w,'file-size',0))
            else:
                w=self._widths.get(col.type,str_width(v)); segs.append((pad_str(v,w), 'date' if col.type=='date' else 'author' if col.type=='author' else 'mode' if col.type=='mode' else 'default',0))
            if i!=len(shown)-1: segs.append((" ",'default',0))
        return segs
    def title(self):
        l=self.current_line()
        if not l: return "[tree]"
        if l.data.get('kind')=='parent':
            return "[tree] Open parent directory"
        if l.data.get('kind')=='header':
            return "[tree]"
        e=l.data.get('entry')
        # count entries only
        idx=0
        for vl in self.lines:
            if vl.data.get('kind') in ('parent','entry'):
                idx+=1
                if vl is l: break
        total=sum(1 for vl in self.lines if vl.data.get('kind') in ('parent','entry'))
        # But when no parent, total=entries count; title says file 1 of 3
        tid=e['id'] if e else self._tree_id
        return f"[tree] {tid} - file {idx} of {total}"
    def current_file(self):
        l=self.current_line()
        if l and l.data.get('entry'): return l.data['entry']['full']
        if l and l.data.get('kind')=='parent': return ".."
        return ""
    def current_blob(self):
        l=self.current_line()
        if l and l.data.get('entry'): return l.data['entry']['id']
        return ""

def format_size_units(n):
    for unit in ['B','K','M','G','T']:
        if n<1024: 
            if unit=='B': return str(n)
            return f"{n:.1f}{unit}"
        n=n/1024
    return f"{n:.1f}P"

