            e['adate']=f"{ats} {atz}"; e['cdate']=f"{cts} {ctz}"
            # author field in -p is name only, no email (author-mail separate)
            # Get email lines?
        # need author-mail parsed above – we ignored. patches: author-mail lines captured? Add second pass? Simplify author name enough.
        return entries
