    # ----- headless / script -----
    def headless_loop(self,first):
        if self.initial_lineno and first.lines:
            first.selected=max(0,min(self.initial_lineno-1,len(first.lines)-1))
        # Build a virtual display for save-display commands (size from COLUMNS/LINES or 80x24 if tty size from /dev/tty ioctl)
        self._headless_size=self.get_terminal_size_from_tty()
        self.build_virtual_display()
        self.run_script_env()
        if self.quit_flag: return 0
        # interactive reading from /dev/tty raw
        # set tty raw using termios if available
        try: import termios, tty as ttymod
        except: termios=None
        fd=self._tty_fd
        old=None
        if termios:
            try: old=termios.tcgetattr(fd); ttymod.setraw(fd)
            except: old=None
        try:
            while not self.quit_flag:
                b=os.read(fd,1)
                if not b: break
                key=self.decode_raw_byte(b,fd)
                if key is None: continue
                self.handle_key(key)
                self.build_virtual_display()
        finally:
            if termios and old:
                try: termios.tcsetattr(fd,termios.TCSADRAIN,old)
                except: pass
        return 0
    def get_terminal_size_from_tty(self):
        # ioctl on tty fd
        try:
            import fcntl, termios, struct
            packed=fcntl.ioctl(self._tty_fd, termios.TIOCGWINSZ, struct.pack("HHHH",0,0,0,0))
            rows,cols,_,_=struct.unpack("HHHH",packed)
            if cols and rows: return cols,rows
        except Exception: pass
        try:
            sz=os.get_terminal_size()
            return sz.columns,sz.lines
        except: return 80,24
    def decode_raw_byte(self,b,fd):
        # return canonical key string
        if b==b'\x1b':
            # peek more with timeout/select
            import select
            # read available bytes
            seq=b
            while True:
                r,_,_=select.select([fd],[],[],0.02)
                if not r: break
                seq+=os.read(fd,1)
                if len(seq)>10: break
                # if seq matches known escape final, break heuristically when last is letter/~
                if seq[-1:] and (seq[-1:].isalpha() or seq[-1:]==b'~'): break
            return self.escape_to_key(seq)
        if b in (b'\r',b'\n'): return '<Enter>'
        if b==b'\t': return '<Tab>'
        if b==b'\x7f' or b==b'\x08': return '<Backspace>'
        if 1<=b[0]<=26:
            if b[0]==3: return '<Ctrl-C>'
            return f"<Ctrl-{chr(64+b[0])}>"
        try: return b.decode('utf-8')
        except: return None
    def escape_to_key(self,seq):
        mapping={b'\x1b[A':'<Up>',b'\x1b[B':'<Down>',b'\x1b[C':'<Right>',b'\x1b[D':'<Left>',b'\x1b[H':'<Home>',b'\x1b[F':'<End>',
                 b'\x1b[5~':'<PageUp>',b'\x1b[6~':'<PageDown>',b'\x1b[2~':'<Insert>',b'\x1b[3~':'<Delete>',b'\x1b[Z':'<ShiftTab>'}
        if seq in mapping: return mapping[seq]
        if len(seq)==2:
            # Esc + char = <Esc>char binding? Return that canonical maybe as 'Esc'+char
            return '<Esc>'+seq[1:].decode('utf-8','ignore')
        return '<Escape>'
