            fg_name='default'; bg_name='default'; attrs_names=()
        key=(fg_name,bg_name)
        if key in self._color_pairs: pair=self._color_pairs[key]
        else:
            curses=self.curses
            fg=COLOR_NAMES.get(str(fg_name).lower(),-1); bg=COLOR_NAMES.get(str(bg_name).lower(),-1)
            # bright colors >7: curses may support 16 colors; map to 0-7 with bold later
            extra_bold=False
            if fg>=8: fg-=8; extra_bold=True
            if bg>=8: bg-=8
            # curses colors 0-7 correspond
            if fg>7: fg=7
            if bg>7: bg=7
