            try: curses.init_pair(pair,fg,bg)
            except: pair=0
            self._color_pairs[key]=(pair,extra_bold)
            pair_val=(pair,extra_bold)
            # store tuple
            self._color_pairs[key]=pair_val
            return pair_val
        return self._color_pairs[key]
    def attr_for_area(self,area):
        # returns curses attribute
        curses=self.curses
        # user color override
        col=self.opts.colors.get(area)
        if col is None:
